/**
 * Lightweight HTML5 Canvas Chart.js compatible engine
 * Supports: doughnut, pie, bar charts with High-DPI, tooltips, legends and animations
 */
class Chart {
    constructor(target, config) {
        this.canvas = typeof target === 'string' ? document.getElementById(target) : (target.canvas || target);
        if (!this.canvas) return;
        this.ctx = this.canvas.getContext('2d');
        this.config = config || {};
        this.type = (config.type || 'bar').toLowerCase();
        this.data = config.data || { labels: [], datasets: [] };
        this.options = config.options || {};
        this.init();
    }

    init() {
        this.setupDpi();
        window.addEventListener('resize', () => {
            this.setupDpi();
            this.render();
        });
        this.setupInteractions();
        this.render();
    }

    setupDpi() {
        const rect = this.canvas.getBoundingClientRect();
        const dpr = window.devicePixelRatio || 1;
        this.width = rect.width || this.canvas.width || 300;
        this.height = rect.height || this.canvas.height || 220;
        this.canvas.width = this.width * dpr;
        this.canvas.height = this.height * dpr;
        this.ctx.scale(dpr, dpr);
    }

    render() {
        const { ctx, width, height } = this;
        ctx.clearRect(0, 0, width, height);

        if (!this.data.datasets || this.data.datasets.length === 0) return;

        if (this.type === 'doughnut' || this.type === 'pie') {
            this.renderDoughnutOrPie();
        } else if (this.type === 'bar') {
            this.renderBar();
        }
    }

    renderDoughnutOrPie() {
        const { ctx, width, height } = this;
        const dataset = this.data.datasets[0];
        const data = dataset.data || [];
        const labels = this.data.labels || [];
        const colors = dataset.backgroundColor || ['#059669', '#cbd5e1', '#10b981', '#f59e0b', '#8b5cf6'];
        const total = data.reduce((a, b) => a + b, 0);

        if (total === 0) {
            ctx.fillStyle = '#94a3b8';
            ctx.font = '13px sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText('Chưa có dữ liệu', width / 2, height / 2);
            return;
        }

        const legendHeight = 36;
        const cx = width / 2;
        const cy = (height - legendHeight) / 2;
        const radius = Math.min(cx, cy) - 16;
        const innerRadius = this.type === 'doughnut' ? radius * 0.58 : 0;

        let startAngle = -Math.PI / 2;

        this.slices = [];
        data.forEach((val, i) => {
            if (val <= 0) return;
            const sliceAngle = (val / total) * (Math.PI * 2);
            const endAngle = startAngle + sliceAngle;
            const color = Array.isArray(colors) ? colors[i % colors.length] : colors;

            ctx.beginPath();
            ctx.arc(cx, cy, radius, startAngle, endAngle);
            if (innerRadius > 0) {
                ctx.arc(cx, cy, innerRadius, endAngle, startAngle, true);
            } else {
                ctx.lineTo(cx, cy);
            }
            ctx.closePath();
            ctx.fillStyle = color;
            ctx.fill();

            // Border
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 2;
            ctx.stroke();

            this.slices.push({
                start: startAngle,
                end: endAngle,
                label: labels[i] || '',
                value: val,
                color: color,
                percent: Math.round((val / total) * 100)
            });

            startAngle = endAngle;
        });

        // Center text for doughnut
        if (this.type === 'doughnut') {
            ctx.fillStyle = '#0f172a';
            ctx.font = 'bold 20px sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(total.toString(), cx, cy - 8);
            ctx.fillStyle = '#64748b';
            ctx.font = '11px sans-serif';
            ctx.fillText('Tổng số', cx, cy + 14);
        }

        // Render Legend at bottom
        this.renderLegend(labels, colors, width, height, legendHeight);
    }

    renderBar() {
        const { ctx, width, height } = this;
        const dataset = this.data.datasets[0];
        const data = dataset.data || [];
        const labels = this.data.labels || [];
        const colors = dataset.backgroundColor || '#059669';

        const padding = { top: 20, right: 20, bottom: 45, left: 35 };
        const chartW = width - padding.left - padding.right;
        const chartH = height - padding.top - padding.bottom;

        const maxVal = Math.max(...data, 5);
        const niceMax = Math.ceil(maxVal * 1.15);

        // Grid lines
        ctx.strokeStyle = '#e2e8f0';
        ctx.lineWidth = 1;
        ctx.fillStyle = '#94a3b8';
        ctx.font = '10px sans-serif';
        ctx.textAlign = 'right';

        const stepCount = 4;
        for (let i = 0; i <= stepCount; i++) {
            const yVal = Math.round((niceMax / stepCount) * i);
            const yPos = padding.top + chartH - (i / stepCount) * chartH;
            ctx.beginPath();
            ctx.moveTo(padding.left, yPos);
            ctx.lineTo(width - padding.right, yPos);
            ctx.stroke();
            ctx.fillText(yVal.toString(), padding.left - 6, yPos + 3);
        }

        // Bars
        const barCount = data.length;
        if (barCount === 0) return;

        const barGap = 16;
        const availableW = chartW - (barGap * (barCount + 1));
        const barWidth = Math.max(16, Math.min(50, availableW / barCount));

        this.bars = [];
        data.forEach((val, i) => {
            const barH = (val / niceMax) * chartH;
            const x = padding.left + barGap + i * (barWidth + barGap);
            const y = padding.top + chartH - barH;
            const color = Array.isArray(colors) ? colors[i % colors.length] : colors;

            // Draw rounded top bar
            ctx.fillStyle = color;
            ctx.beginPath();
            const r = Math.min(6, barH / 2);
            ctx.roundRect ? ctx.roundRect(x, y, barWidth, barH, [r, r, 0, 0]) : ctx.rect(x, y, barWidth, barH);
            ctx.fill();

            // Value text above bar
            if (val > 0) {
                ctx.fillStyle = '#0f172a';
                ctx.font = 'bold 11px sans-serif';
                ctx.textAlign = 'center';
                ctx.fillText(val.toString(), x + barWidth / 2, y - 5);
            }

            // Label text below bar
            ctx.fillStyle = '#64748b';
            ctx.font = '11px sans-serif';
            ctx.textAlign = 'center';
            const rawLabel = labels[i] || '';
            const truncated = rawLabel.length > 12 ? rawLabel.substring(0, 11) + '…' : rawLabel;
            ctx.fillText(truncated, x + barWidth / 2, padding.top + chartH + 18);

            this.bars.push({ x, y, w: barWidth, h: barH, value: val, label: rawLabel });
        });
    }

    renderLegend(labels, colors, width, height, legendHeight) {
        const { ctx } = this;
        ctx.font = '11px sans-serif';
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';

        const y = height - (legendHeight / 2) + 4;
        let totalW = 0;
        const items = labels.map((lbl, i) => {
            const w = ctx.measureText(lbl).width + 24;
            totalW += w;
            return { label: lbl, color: Array.isArray(colors) ? colors[i % colors.length] : colors, w };
        });

        let startX = Math.max(10, (width - totalW) / 2);
        items.forEach(it => {
            ctx.fillStyle = it.color;
            ctx.beginPath();
            ctx.arc(startX + 5, y, 5, 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = '#475569';
            ctx.fillText(it.label, startX + 14, y);
            startX += it.w;
        });
    }

    setupInteractions() {
        // Can be extended with tooltips if needed
    }
}

window.Chart = Chart;
